create table public.payments(id uuid primary key default gen_random_uuid(),reservation_id uuid not null references public.reservations,amount bigint not null check(amount>0),intent text not null check(intent in ('partial','full','balance')),status public.payment_status not null default 'pending',external_session_id text unique,external_payment_id text unique,checkout_url text,provider_claimed_at timestamptz,expires_at timestamptz not null default now()+interval '24 hours',created_at timestamptz not null default now());
create unique index one_pending_checkout on public.payments(reservation_id) where status='pending';
create index payments_reservation_created on public.payments(reservation_id,created_at);
create table public.balances(reservation_id uuid primary key references public.reservations,amount bigint not null check(amount>=0),updated_at timestamptz not null default now());
create table public.transactions(id uuid primary key default gen_random_uuid(),reservation_id uuid not null references public.reservations,payment_id uuid references public.payments,kind text not null check(kind in ('payment','refund')),amount bigint not null check(amount>0),reference text not null unique,created_at timestamptz not null default now());
create table public.cancellations(id uuid primary key default gen_random_uuid(),reservation_id uuid not null references public.reservations,reason text not null check(length(reason) between 5 and 2000),previous_status public.reservation_status not null,status public.refund_status not null default 'pending',created_at timestamptz not null default now());
create unique index one_pending_cancel on public.cancellations(reservation_id) where status='pending';
create table public.refunds(id uuid primary key default gen_random_uuid(),reservation_id uuid not null unique references public.reservations,eligible_amount bigint not null check(eligible_amount>0),status public.refund_status not null default 'pending',external_refund_ids jsonb not null default '[]',processing boolean not null default false,created_at timestamptz not null default now());
create table public.refund_operations(id uuid primary key default gen_random_uuid(),refund_id uuid not null references public.refunds,payment_id uuid not null references public.payments,amount bigint not null check(amount>0),claimed boolean not null default false,external_refund_id text unique,status text not null default 'not_started' check(status in ('not_started','pending','processing','succeeded','failed')),unique(refund_id,payment_id));
create table public.webhook_events(id text primary key,event_type text not null,created_at timestamptz not null default now());
